from typing import Protocol


class ThumbnailRenderer(Protocol):
    def render(self, photo_id: int) -> bytes: ...


def render_thumbnails(photo_ids: list[int], renderer: ThumbnailRenderer) -> None:
    for photo_id in photo_ids:
        renderer.render(photo_id)

